#include "stdlib/blas/ext/base/ndarray/dindex_of_falsy.h"
#include "stdlib/blas/ext/base/dindex_of_falsy.h"
#include "stdlib/ndarray/base/clip_index.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdint.h>

/**
* Returns the first index of a falsy value in a one-dimensional double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* -   If unable to find a falsy value, the function returns `-1`.
*
* @param arrays    list containing ndarrays
* @return          index
*/
CBLAS_INT stdlib_blas_ext_dindex_of_falsy( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	int32_t fromIndex;
	stdlib_ndarray_get_int32( arrays[ 1 ], NULL, &fromIndex );

	CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );
	fromIndex = (int32_t)stdlib_ndarray_clip_index( (int64_t)fromIndex, (int64_t)N );
	if ( fromIndex >= N ) {
		return -1;
	}
	N -= (CBLAS_INT)fromIndex;

	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x ) + ( strideX*(CBLAS_INT)fromIndex );

	CBLAS_INT idx = API_SUFFIX(stdlib_strided_dindex_of_falsy_ndarray)( N, (const double *)stdlib_ndarray_data( x ), strideX, offsetX );
	if ( idx >= 0 ) {
		idx += (CBLAS_INT)fromIndex;
	}
	return idx;
}
